export interface LabelProvider {
  read(): Promise<unknown>;
}

export type LabelCountResult =
  | { readonly ok: true; readonly count: number }
  | { readonly ok: false; readonly message: string };

export class LabelCounter {
  public constructor(private readonly provider: LabelProvider) {}

  public async count(): Promise<LabelCountResult> {
    try {
      const value = await this.provider.read();
      if (!Array.isArray(value) || value.some((item) => typeof item !== "string")) {
        return { ok: false, message: "Invalid label data" };
      }

      const normalized = value
        .map((item) => (item as string).trim().toLowerCase())
        .filter((item) => item.length > 0);
      return { ok: true, count: normalized.length };
    } catch (error: unknown) {
      return {
        ok: false,
        message: error instanceof Error ? error.message : "Unable to read labels",
      };
    }
  }
}

