import { LabelCounter } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function assertJson(actual: unknown, expected: unknown, message: string): void {
  assert(JSON.stringify(actual) === JSON.stringify(expected), message);
}

async function run(): Promise<void> {
  const labels = [" Alpha ", "alpha", "BETA", "  ", "beta", "Gamma"];
  const counter = new LabelCounter({ read: async () => labels });
  assertJson(await counter.count(), { ok: true, count: 3 }, "normalization and distinct counting");
  assertJson(labels, [" Alpha ", "alpha", "BETA", "  ", "beta", "Gamma"], "input must not be mutated");

  assertJson(await new LabelCounter({ read: async () => [] }).count(), { ok: true, count: 0 }, "empty array");
  assertJson(await new LabelCounter({ read: async () => "alpha" }).count(), { ok: false, message: "Invalid label data" }, "non-array data");
  assertJson(await new LabelCounter({ read: async () => ["alpha", 2, "beta"] }).count(), { ok: false, message: "Invalid label data" }, "non-string array member");

  assertJson(
    await new LabelCounter({ read: async () => { throw new Error("provider failed"); } }).count(),
    { ok: false, message: "provider failed" },
    "Error rejection message",
  );
  assertJson(
    await new LabelCounter({ read: async () => { throw "failure"; } }).count(),
    { ok: false, message: "Unable to read labels" },
    "non-Error rejection fallback",
  );

  const reusable = ["one"];
  const reusableCounter = new LabelCounter({ read: async () => reusable });
  assertJson(await reusableCounter.count(), { ok: true, count: 1 }, "first reusable read");
  reusable.push("two");
  assertJson(await reusableCounter.count(), { ok: true, count: 2 }, "each count must use newly read data");
}

run().catch((error: unknown) => { throw error; });

